1	import Foundation
2	import SwiftData
3	import WCIWKit
4	
5	@MainActor
6	final class WatchlistManager: ObservableObject {
7	    static let shared = WatchlistManager()
8	
9	    private static let lastRefreshKey = "watchlistLastRefresh"
10	
11	    private let tmdbService: TMDBService?
12	
13	    private let defaults: UserDefaults
14	
15	    let refreshPolicy: WatchlistRefreshPolicy
16	
17	    @Published private(set) var isRefreshing = false
18	
19	    var lastRefreshDate: Date? {
20	        get { defaults.object(forKey: Self.lastRefreshKey) as? Date }
21	        set { defaults.set(newValue, forKey: Self.lastRefreshKey) }
22	    }
23	
24	    init(
25	        tmdbService: TMDBService? = nil,
26	        defaults: UserDefaults = .standard,
27	        refreshPolicy: WatchlistRefreshPolicy = WatchlistRefreshPolicy()
28	    ) {
29	        self.tmdbService = tmdbService ?? (try? TMDBService())
30	        self.defaults = defaults
31	        self.refreshPolicy = refreshPolicy
32	    }
33	
34	    // MARK: - Add/Remove Operations
35	
36	    @discardableResult
37	    func addToWatchlist(_ media: Media, context: ModelContext, posterData: Data? = nil) async -> WatchlistItem? {
38	        // Check if already in watchlist
39	        if isInWatchlist(mediaId: media.id, context: context) {
40	            return nil
41	        }
42	
43	        // For TV shows, fetch airing info
44	        var airingInfo: TVShowAiringInfo?
45	        if media.mediaType == .tv, let service = tmdbService {
46	            do {
47	                airingInfo = try await service.getTVShowAiringInfo(tvId: media.id)
48	            } catch {
49	                // Continue with nil airing info if fetch fails
50	            }
51	        }
52	
53	        // Create and insert the item
54	        let item = WatchlistItem(from: media, airingInfo: airingInfo, posterData: posterData)
55	        context.insert(item)
56	
57	        // Request notification permission if not yet determined
58	        await NotificationManager.shared.requestPermissionIfNeeded()
59	
60	        return item
61	    }
62	
63	    @discardableResult
64	    func removeFromWatchlist(mediaId: Int, context: ModelContext) -> Bool {
65	        guard let item = fetchWatchlistItem(mediaId: mediaId, context: context) else {
66	            return false
67	        }
68	        context.delete(item)
69	
70	        // Cascade: delete all watched episode records for this show
71	        let descriptor = FetchDescriptor<WatchedEpisode>(
72	            predicate: #Predicate { $0.mediaId == mediaId }
73	        )
74	        if let episodes = try? context.fetch(descriptor) {
75	            for episode in episodes {
76	                context.delete(episode)
77	            }
78	        }
79	
80	        return true
81	    }
82	
83	    func isInWatchlist(mediaId: Int, context: ModelContext) -> Bool {
84	        fetchWatchlistItem(mediaId: mediaId, context: context) != nil
85	    }
86	
87	    func fetchWatchlistItem(mediaId: Int, context: ModelContext) -> WatchlistItem? {
88	        let descriptor = FetchDescriptor<WatchlistItem>(
89	            predicate: #Predicate { $0.mediaId == mediaId }
90	        )
91	        return try? context.fetch(descriptor).first
92	    }
93	
94	    func fetchAllWatchlistItems(context: ModelContext) -> [WatchlistItem] {
95	        let descriptor = FetchDescriptor<WatchlistItem>(
96	            sortBy: [SortDescriptor(\.dateAdded, order: .reverse)]
97	        )
98	        return (try? context.fetch(descriptor)) ?? []
99	    }
100	
101	    // MARK: - Refresh Logic
102	
103	    func needsRefresh(currentDate: Date = Date()) -> Bool {
104	        refreshPolicy.needsRefresh(lastRefreshDate: lastRefreshDate, currentDate: currentDate)
105	    }
106	
107	    func refreshIfNeeded(context: ModelContext, force: Bool = false, currentDate: Date = Date()) async {
108	        guard force || needsRefresh(currentDate: currentDate) else {
109	            return
110	        }
111	
112	        await refreshAllAiringInfo(context: context)
113	        lastRefreshDate = currentDate
114	    }
115	
116	    func refreshAllAiringInfo(context: ModelContext) async {
117	        guard let service = tmdbService else { return }
118	
119	        isRefreshing = true
120	        defer { isRefreshing = false }
121	
122	        let items = fetchAllWatchlistItems(context: context)
123	
124	        for item in items {
125	            // Only refresh TV shows, not movies
126	            guard item.isTVShow else { continue }
127	
128	            do {
129	                let airingInfo = try await service.getTVShowAiringInfo(tvId: item.mediaId)
130	                item.update(with: airingInfo)
131	            } catch {
132	                // Keep existing data if refresh fails
133	            }
134	        }
135	
136	        // Explicitly save changes to persist updated airing info
137	        try? context.save()
138	
139	        // Reschedule episode notifications with updated airing data
140	        await NotificationManager.shared.rescheduleEpisodeNotifications(items: items)
141	    }
142	
143	    func refreshAiringInfo(for item: WatchlistItem, context: ModelContext) async {
144	        // Only refresh TV shows, not movies
145	        guard item.isTVShow, let service = tmdbService else { return }
146	
147	        do {
148	            let airingInfo = try await service.getTVShowAiringInfo(tvId: item.mediaId)
149	            item.update(with: airingInfo)
150	            try? context.save()
151	        } catch {
152	            // Keep existing data if refresh fails
153	        }
154	    }
155	
156	    // MARK: - Episode Tracking
157	
158	    func markEpisodeWatched(
159	        mediaId: Int,
160	        episodeId: Int,
161	        seasonNumber: Int,
162	        episodeNumber: Int,
163	        context: ModelContext
164	    ) {
165	        guard !isEpisodeWatched(episodeId: episodeId, context: context) else { return }
166	
167	        let record = WatchedEpisode(
168	            episodeId: episodeId,
169	            mediaId: mediaId,
170	            seasonNumber: seasonNumber,
171	            episodeNumber: episodeNumber
172	        )
173	        context.insert(record)
174	    }
175	
176	    func markEpisodeUnwatched(episodeId: Int, context: ModelContext) {
177	        let descriptor = FetchDescriptor<WatchedEpisode>(
178	            predicate: #Predicate { $0.episodeId == episodeId }
179	        )
180	        guard let record = try? context.fetch(descriptor).first else { return }
181	        context.delete(record)
182	    }
183	
184	    @discardableResult
185	    func toggleEpisodeWatched(
186	        mediaId: Int,
187	        episodeId: Int,
188	        seasonNumber: Int,
189	        episodeNumber: Int,
190	        context: ModelContext
191	    ) -> Bool {
192	        if isEpisodeWatched(episodeId: episodeId, context: context) {
193	            markEpisodeUnwatched(episodeId: episodeId, context: context)
194	            return false
195	        } else {
196	            markEpisodeWatched(
197	                mediaId: mediaId,
198	                episodeId: episodeId,
199	                seasonNumber: seasonNumber,
200	                episodeNumber: episodeNumber,
201	                context: context
202	            )
203	            return true
204	        }
205	    }
206	
207	    func isEpisodeWatched(episodeId: Int, context: ModelContext) -> Bool {
208	        let descriptor = FetchDescriptor<WatchedEpisode>(
209	            predicate: #Predicate { $0.episodeId == episodeId }
210	        )
211	        let count = (try? context.fetchCount(descriptor)) ?? 0
212	        return count > 0
213	    }
214	
215	    func watchedEpisodes(for mediaId: Int, context: ModelContext) -> [WatchedEpisode] {
216	        let descriptor = FetchDescriptor<WatchedEpisode>(
217	            predicate: #Predicate { $0.mediaId == mediaId }
218	        )
219	        return (try? context.fetch(descriptor)) ?? []
220	    }
221	
222	    func watchedEpisodeCount(for mediaId: Int, seasonNumber: Int, context: ModelContext) -> Int {
223	        let descriptor = FetchDescriptor<WatchedEpisode>(
224	            predicate: #Predicate { $0.mediaId == mediaId && $0.seasonNumber == seasonNumber }
225	        )
226	        return (try? context.fetchCount(descriptor)) ?? 0
227	    }
228	
229	    func markSeasonWatched(mediaId: Int, episodes: [Episode], context: ModelContext) {
230	        for episode in episodes {
231	            markEpisodeWatched(
232	                mediaId: mediaId,
233	                episodeId: episode.id,
234	                seasonNumber: episode.seasonNumber,
235	                episodeNumber: episode.episodeNumber,
236	                context: context
237	            )
238	        }
239	    }
240	
241	    func markSeasonUnwatched(mediaId: Int, seasonNumber: Int, context: ModelContext) {
242	        let descriptor = FetchDescriptor<WatchedEpisode>(
243	            predicate: #Predicate { $0.mediaId == mediaId && $0.seasonNumber == seasonNumber }
244	        )
245	        guard let episodes = try? context.fetch(descriptor) else { return }
246	        for episode in episodes {
247	            context.delete(episode)
248	        }
249	    }
250	
251	}
