5	enum WatchlistCardHeight {
6	    static let standard: CGFloat = 140
7	}
8	
9	struct WatchlistCardView: View {
10	    let item: WatchlistItem
11	
12	    @Environment(\.modelContext) private var modelContext
13	
14	    private var countdownText: String? {
15	        let airingInfo = TVShowAiringInfo(
16	            status: item.status,
17	            nextEpisodeDate: item.nextEpisodeDate,
18	            nextEpisodeNumber: item.nextEpisodeNumber,
19	            nextSeasonNumber: item.nextSeasonNumber
20	        )
21	        return airingInfo.countdownText
22	    }
23	
24	    private var isComplete: Bool {
25	        item.status == .ended || item.status == .cancelled
26	    }
27	
28	    private var badgeText: String? {
29	        if item.isMovie {
30	            return "Movie"
31	        }
32	        if let countdown = countdownText {
33	            return countdown
34	        } else if isComplete {
35	            return "Complete"
36	        } else if item.status == .returning {
37	            return "Returning"
38	        }
39	        return nil
40	    }
41	
42	    private var badgeColor: Color {
43	        if item.isMovie {
44	            return .blue
45	        }
46	        switch item.status {
47	        case .airing:
48	            return AppColor.watching
49	        case .returning:
50	            return .orange
51	        case .ended, .cancelled:
52	            return .secondary
53	        case .unknown:
54	            return .secondary
55	        }
56	    }
57	
58	    var body: some View {
59	        cardContent
60	            .swipeActions(edge: .trailing, allowsFullSwipe: true) {
61	                Button(role: .destructive) {
62	                    removeFromWatchlist()
63	                } label: {
64	                    Label("Remove", systemImage: "trash.fill")
65	                }
66	            }
67	            .swipeActions(edge: .leading, allowsFullSwipe: true) {
68	                if item.isWatched {
69	                    Button {
70	                        markAsUnwatched()
71	                    } label: {
72	                        Label("Unwatched", systemImage: "eye.slash.fill")
73	                    }
74	                    .tint(.orange)
75	                } else {
76	                    Button {
77	                        markAsWatched()
78	                    } label: {
79	                        Label("Watched", systemImage: "eye.fill")
80	                    }
81	                    .tint(.green)
82	                }
83	            }
84	            .contextMenu {
85	                if item.isWatched {
86	                    Button {
87	                        markAsUnwatched()
88	                    } label: {
89	                        Label("Mark as Unwatched", systemImage: "eye.slash.fill")
90	                    }
91	                } else {
92	                    Button {
93	                        markAsWatched()
94	                    } label: {
95	                        Label("Mark as Watched", systemImage: "eye.fill")
96	                    }
97	                }
98	
99	                Button(role: .destructive) {
100	                    removeFromWatchlist()
101	                } label: {
102	                    Label("Remove from Watchlist", systemImage: "trash.fill")
103	                }
104	            }
105	    }
106	
107	    private var cardContent: some View {
108	        ZStack(alignment: .bottomLeading) {
109	            // Background image
110	            backdropImage
111	
112	            // Gradient overlay
113	            LinearGradient(
114	                colors: [.clear, .black.opacity(0.8)],
115	                startPoint: .top,
116	                endPoint: .bottom
117	            )
118	
119	            // Content overlay
120	            VStack(alignment: .leading, spacing: Spacing.xs) {
121	                Spacer()
122	
123	                // Title
124	                Text(item.title)
125	                    .font(.headline)
126	                    .fontWeight(.bold)
127	                    .foregroundStyle(.white)
128	                    .lineLimit(2)
129	                    .shadow(color: .black.opacity(0.5), radius: 2, x: 0, y: 1)
130	            }
131	            .padding(Spacing.md)
132	
133	            // Badge (top-right)
134	            if let badge = badgeText {
135	                VStack {
136	                    HStack {
137	                        Spacer()
138	                        Text(badge)
139	                            .font(.caption)
140	                            .fontWeight(.semibold)
141	                            .foregroundStyle(.white)
142	                            .padding(.horizontal, Spacing.sm)
143	                            .padding(.vertical, Spacing.xs)
144	                            .background(badgeColor.opacity(0.9))
145	                            .clipShape(Capsule())
146	                            .shadow(color: .black.opacity(0.3), radius: 2, x: 0, y: 1)
147	                    }
148	                    Spacer()
149	                }
150	                .padding(Spacing.sm)
151	            }
152	        }
153	        .frame(height: WatchlistCardHeight.standard)
154	        .clipShape(RoundedRectangle(cornerRadius: CornerRadius.xl))
155	    }
156	
157	    private func markAsWatched() {
158	        HapticManager.mediumImpact()
159	        withAnimation {
160	            item.watchState = .watched
161	        }
162	        NotificationManager.shared.cancelNotifications(for: item.mediaId)
163	    }
164	
165	    private func markAsUnwatched() {
166	        HapticManager.mediumImpact()
167	        withAnimation {
168	            item.watchState = .tracking
169	        }
170	    }
171	
172	    private func removeFromWatchlist() {
173	        HapticManager.mediumImpact()
174	        modelContext.delete(item)
175	    }
176	
177	    // MARK: - Backdrop Image
178	
179	    @ViewBuilder
180	    private var backdropImage: some View {
181	        if let backdropURL = item.backdropURL {
182	            // Use backdrop if available
183	            CachedAsyncImage(url: backdropURL) { phase in
184	                switch phase {
185	                case .success(let image):
186	                    image
