import Foundation
import UserNotifications
import SwiftData
import WCIWKit

@MainActor
final class NotificationManager: ObservableObject {
    static let shared = NotificationManager()

    @Published private(set) var isAuthorized = false

    @Published var pendingMediaId: Int?
    @Published var pendingMediaType: MediaType?

    private static let notificationsEnabledKey = "notificationsEnabled"

    private static let lastOpenedDateKey = "lastOpenedDate"

    var lastOpenedDate: Date {
        get {
            let interval = UserDefaults.standard.double(forKey: Self.lastOpenedDateKey)
            return interval > 0 ? Date(timeIntervalSince1970: interval) : .distantPast
        }
        set {
            UserDefaults.standard.set(newValue.timeIntervalSince1970, forKey: Self.lastOpenedDateKey)
        }
    }

    var notificationsEnabled: Bool {
        get { UserDefaults.standard.bool(forKey: Self.notificationsEnabledKey) }
        set { UserDefaults.standard.set(newValue, forKey: Self.notificationsEnabledKey) }
    }

    private init() {
        Task { await refreshAuthorizationStatus() }
    }

    // MARK: - Permission

    func requestPermission() async -> Bool {
        do {
            let granted = try await UNUserNotificationCenter.current()
                .requestAuthorization(options: [.alert, .badge, .sound])
            isAuthorized = granted
            if granted {
                notificationsEnabled = true
            }
            return granted
        } catch {
            return false
        }
    }

    func requestPermissionIfNeeded() async {
        let settings = await UNUserNotificationCenter.current().notificationSettings()
        guard settings.authorizationStatus == .notDetermined else { return }
        _ = await requestPermission()
    }

    func refreshAuthorizationStatus() async {
        let settings = await UNUserNotificationCenter.current().notificationSettings()
        isAuthorized = settings.authorizationStatus == .authorized
    }

    func shouldScheduleNotifications() -> Bool {
        isAuthorized && notificationsEnabled
    }

    // MARK: - Episode Notifications

    func rescheduleEpisodeNotifications(items: [WatchlistItem]) async {
        guard shouldScheduleNotifications() else { return }

        let center = UNUserNotificationCenter.current()

        // Remove all existing episode notifications
        let pendingRequests = await center.pendingNotificationRequests()
        let episodeIds = pendingRequests
            .filter { $0.identifier.hasPrefix("episode-") }
            .map(\.identifier)
        center.removePendingNotificationRequests(withIdentifiers: episodeIds)

        // Build content for all eligible episodes
        var contentItems: [(content: NotificationContent, airDate: Date)] = []
        for item in items where item.isTVShow {
            guard let airDate = item.nextEpisodeDate else { continue }

            guard let content = NotificationContentBuilder.episodeNotification(
                mediaId: item.mediaId,
                title: item.title,
                seasonNumber: item.nextSeasonNumber,
                episodeNumber: item.nextEpisodeNumber,
                episodeName: item.nextEpisodeName,
                airDate: airDate
            ) else { continue }

            contentItems.append((content, airDate))
        }

        // Schedule chronologically so badge values (1, 2, 3...) match air order
        let sortedItems = contentItems.sorted { $0.airDate < $1.airDate }
        var badgeOffset = 0
        for (content, airDate) in sortedItems {
            if airDate > lastOpenedDate {
                badgeOffset += 1
                await scheduleNotification(content, badgeCount: badgeOffset)
            } else {
                await scheduleNotification(content)
            }
